-- Security, operations, privacy, POS and driver review completion.
create table if not exists public.user_security (user_id uuid primary key references auth.users(id) on delete cascade,pin_hash text,pin_failed_attempts integer not null default 0 check(pin_failed_attempts>=0),pin_locked_until timestamptz,last_pin_verified_at timestamptz,updated_at timestamptz not null default now());
alter table public.user_security enable row level security; revoke all on public.user_security from anon,authenticated;
create table if not exists public.trusted_devices (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,token_hash text not null,device_label text not null default 'device',trusted_until timestamptz not null,last_seen_at timestamptz not null default now(),created_at timestamptz not null default now(),revoked_at timestamptz,unique(user_id,token_hash));
alter table public.trusted_devices enable row level security; revoke all on public.trusted_devices from anon,authenticated; create index if not exists trusted_devices_user_active_idx on public.trusted_devices(user_id,trusted_until) where revoked_at is null;
create table if not exists public.app_settings (key text primary key,value jsonb not null,is_public boolean not null default false,updated_at timestamptz not null default now(),updated_by uuid references auth.users(id)); alter table public.app_settings enable row level security;
drop policy if exists app_settings_public_read on public.app_settings; create policy app_settings_public_read on public.app_settings for select to anon,authenticated using(is_public=true or public.is_admin());
drop policy if exists app_settings_admin_all on public.app_settings; create policy app_settings_admin_all on public.app_settings for all to authenticated using(public.is_admin()) with check(public.is_admin()); grant select on public.app_settings to anon,authenticated; grant insert,update,delete on public.app_settings to authenticated;
insert into public.app_settings(key,value,is_public) values ('maintenance_mode','false'::jsonb,true),('driver_capacity','5'::jsonb,false),('delivery_base_fee','0'::jsonb,true),('delivery_per_km','0'::jsonb,true) on conflict(key) do nothing;
create table if not exists public.service_areas (id uuid primary key default gen_random_uuid(),name text not null,enabled boolean not null default true,center_latitude double precision,center_longitude double precision,radius_km numeric(8,2),created_at timestamptz not null default now(),updated_at timestamptz not null default now()); alter table public.service_areas enable row level security;
drop policy if exists service_areas_public_read on public.service_areas; create policy service_areas_public_read on public.service_areas for select to anon,authenticated using(enabled=true or public.is_admin()); drop policy if exists service_areas_admin_all on public.service_areas; create policy service_areas_admin_all on public.service_areas for all to authenticated using(public.is_admin()) with check(public.is_admin()); grant select on public.service_areas to anon,authenticated; grant insert,update,delete on public.service_areas to authenticated;
create table if not exists public.push_tokens (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,token text not null,platform text not null check(platform in ('android','web','ios')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,token)); alter table public.push_tokens enable row level security; drop policy if exists push_tokens_own on public.push_tokens; create policy push_tokens_own on public.push_tokens for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid())); grant select,insert,update,delete on public.push_tokens to authenticated;
create table if not exists public.deletion_requests (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,status text not null default 'pending' check(status in ('pending','processing','completed','rejected')),reason text not null default '',created_at timestamptz not null default now(),resolved_at timestamptz,admin_note text not null default ''); alter table public.deletion_requests enable row level security; drop policy if exists deletion_requests_own_read on public.deletion_requests; create policy deletion_requests_own_read on public.deletion_requests for select to authenticated using(user_id=(select auth.uid()) or public.is_admin()); drop policy if exists deletion_requests_own_insert on public.deletion_requests; create policy deletion_requests_own_insert on public.deletion_requests for insert to authenticated with check(user_id=(select auth.uid())); drop policy if exists deletion_requests_admin_update on public.deletion_requests; create policy deletion_requests_admin_update on public.deletion_requests for update to authenticated using(public.is_admin()) with check(public.is_admin()); grant select,insert,update on public.deletion_requests to authenticated;
create table if not exists public.driver_issues (id uuid primary key default gen_random_uuid(),driver_id uuid not null references auth.users(id) on delete cascade,order_id uuid references public.orders(id) on delete set null,category text not null check(category in ('wrong_address','customer_unavailable','merchant_delay','vehicle_route','other')),message text not null default '',status text not null default 'open' check(status in ('open','in_progress','resolved','closed')),admin_note text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now()); alter table public.driver_issues enable row level security; drop policy if exists driver_issues_own_read on public.driver_issues; create policy driver_issues_own_read on public.driver_issues for select to authenticated using(driver_id=(select auth.uid()) or public.is_admin()); drop policy if exists driver_issues_own_insert on public.driver_issues; create policy driver_issues_own_insert on public.driver_issues for insert to authenticated with check(driver_id=(select auth.uid()) and public.has_role('driver'::public.app_role)); drop policy if exists driver_issues_admin_update on public.driver_issues; create policy driver_issues_admin_update on public.driver_issues for update to authenticated using(public.is_admin()) with check(public.is_admin()); grant select,insert,update on public.driver_issues to authenticated;
create table if not exists public.store_hours (id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id) on delete cascade,weekday smallint not null check(weekday between 0 and 6),opens_at time,closes_at time,is_closed boolean not null default false,unique(store_id,weekday)); alter table public.store_hours enable row level security; drop policy if exists store_hours_public_read on public.store_hours; create policy store_hours_public_read on public.store_hours for select to anon,authenticated using(true); drop policy if exists store_hours_owner_all on public.store_hours; create policy store_hours_owner_all on public.store_hours for all to authenticated using(exists(select 1 from public.stores s where s.id=store_id and (s.owner_id=(select auth.uid()) or public.is_admin()))) with check(exists(select 1 from public.stores s where s.id=store_id and (s.owner_id=(select auth.uid()) or public.is_admin()))); grant select on public.store_hours to anon,authenticated; grant insert,update,delete on public.store_hours to authenticated;
create table if not exists public.pos_sales (id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id) on delete restrict,actor_id uuid not null references auth.users(id),total numeric(12,2) not null default 0 check(total>=0),note text not null default '',created_at timestamptz not null default now()); create table if not exists public.pos_sale_items (id uuid primary key default gen_random_uuid(),sale_id uuid not null references public.pos_sales(id) on delete cascade,menu_item_id uuid references public.menu_items(id) on delete set null,name_snapshot text not null,unit_price numeric(12,2) not null check(unit_price>=0),quantity integer not null check(quantity>0),line_total numeric(12,2) generated always as(unit_price*quantity) stored); alter table public.pos_sales enable row level security; alter table public.pos_sale_items enable row level security; drop policy if exists pos_sales_owner on public.pos_sales; create policy pos_sales_owner on public.pos_sales for select to authenticated using(exists(select 1 from public.stores s where s.id=store_id and (s.owner_id=(select auth.uid()) or public.is_admin()))); drop policy if exists pos_sale_items_owner on public.pos_sale_items; create policy pos_sale_items_owner on public.pos_sale_items for select to authenticated using(exists(select 1 from public.pos_sales ps join public.stores s on s.id=ps.store_id where ps.id=sale_id and (s.owner_id=(select auth.uid()) or public.is_admin()))); grant select on public.pos_sales,public.pos_sale_items to authenticated;
create table if not exists public.driver_reviews (id uuid primary key default gen_random_uuid(),order_id uuid not null unique references public.orders(id) on delete cascade,driver_id uuid not null references auth.users(id) on delete cascade,customer_id uuid not null references auth.users(id) on delete cascade,rating integer not null check(rating between 1 and 5),comment text not null default '',created_at timestamptz not null default now()); alter table public.driver_reviews enable row level security; drop policy if exists driver_reviews_public_read on public.driver_reviews; create policy driver_reviews_public_read on public.driver_reviews for select to authenticated using(customer_id=(select auth.uid()) or driver_id=(select auth.uid()) or public.is_admin()); grant select on public.driver_reviews to authenticated;
create or replace function public.set_pin(p_pin text) returns boolean language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_pin !~ '^[0-9]{4,8}$' then raise exception 'PIN must be 4-8 digits'; end if; insert into public.user_security(user_id,pin_hash,pin_failed_attempts,pin_locked_until,updated_at) values(auth.uid(),crypt(p_pin,gen_salt('bf',10)),0,null,now()) on conflict(user_id) do update set pin_hash=excluded.pin_hash,pin_failed_attempts=0,pin_locked_until=null,updated_at=now(); return true; end $$; revoke all on function public.set_pin(text) from public,anon; grant execute on function public.set_pin(text) to authenticated;
create or replace function public.verify_pin(p_pin text,p_device_token text default null,p_device_label text default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare s public.user_security%rowtype; v_hash text; v_until timestamptz; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select * into s from public.user_security where user_id=auth.uid() for update; if not found or s.pin_hash is null then raise exception 'PIN is not configured'; end if; if s.pin_locked_until is not null and s.pin_locked_until>now() then return jsonb_build_object('ok',false,'locked_until',s.pin_locked_until); end if; if crypt(p_pin,s.pin_hash)<>s.pin_hash then update public.user_security set pin_failed_attempts=pin_failed_attempts+1,pin_locked_until=case when pin_failed_attempts+1>=5 then now()+interval '15 minutes' else null end,updated_at=now() where user_id=auth.uid(); select pin_locked_until into v_until from public.user_security where user_id=auth.uid(); return jsonb_build_object('ok',false,'locked_until',v_until); end if; update public.user_security set pin_failed_attempts=0,pin_locked_until=null,last_pin_verified_at=now(),updated_at=now() where user_id=auth.uid(); if nullif(p_device_token,'') is not null then v_hash:=encode(digest(p_device_token,'sha256'),'hex'); v_until:=now()+interval '48 hours'; insert into public.trusted_devices(user_id,token_hash,device_label,trusted_until,last_seen_at,revoked_at) values(auth.uid(),v_hash,left(coalesce(nullif(p_device_label,''),'device'),120),v_until,now(),null) on conflict(user_id,token_hash) do update set trusted_until=excluded.trusted_until,last_seen_at=now(),revoked_at=null,device_label=excluded.device_label; end if; return jsonb_build_object('ok',true,'trusted_until',v_until,'last_pin_verified_at',now()); end $$; revoke all on function public.verify_pin(text,text,text) from public,anon; grant execute on function public.verify_pin(text,text,text) to authenticated;
create or replace function public.get_security_status(p_device_token text default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare s public.user_security%rowtype; d public.trusted_devices%rowtype; v_hash text; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select * into s from public.user_security where user_id=auth.uid(); if nullif(p_device_token,'') is not null then v_hash:=encode(digest(p_device_token,'sha256'),'hex'); select * into d from public.trusted_devices where user_id=auth.uid() and token_hash=v_hash and revoked_at is null and trusted_until>now(); if found then update public.trusted_devices set last_seen_at=now() where id=d.id; end if; end if; return jsonb_build_object('has_pin',coalesce(s.pin_hash is not null,false),'locked_until',s.pin_locked_until,'last_pin_verified_at',s.last_pin_verified_at,'device_trusted',d.id is not null,'trusted_until',d.trusted_until); end $$; revoke all on function public.get_security_status(text) from public,anon; grant execute on function public.get_security_status(text) to authenticated;
create or replace function public.revoke_trusted_devices() returns integer language plpgsql security definer set search_path='' as $$ declare n integer; begin if auth.uid() is null then raise exception 'Authentication required'; end if; update public.trusted_devices set revoked_at=now() where user_id=auth.uid() and revoked_at is null; get diagnostics n=row_count; return n; end $$; revoke all on function public.revoke_trusted_devices() from public,anon; grant execute on function public.revoke_trusted_devices() to authenticated;
create or replace function public.submit_driver_review(p_order_id uuid,p_rating integer,p_comment text default '') returns public.driver_reviews language plpgsql security definer set search_path='' as $$ declare o public.orders%rowtype; r public.driver_reviews%rowtype; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_rating<1 or p_rating>5 then raise exception 'Invalid rating'; end if; select * into o from public.orders where id=p_order_id and customer_id=auth.uid() and status='delivered' and driver_id is not null; if not found then raise exception 'Only delivered own orders can be reviewed'; end if; insert into public.driver_reviews(order_id,driver_id,customer_id,rating,comment) values(o.id,o.driver_id,auth.uid(),p_rating,left(coalesce(trim(p_comment),''),1000)) returning * into r; return r; end $$; revoke all on function public.submit_driver_review(uuid,integer,text) from public,anon; grant execute on function public.submit_driver_review(uuid,integer,text) to authenticated;
create or replace function public.create_pos_sale(p_store_id uuid,p_items jsonb,p_note text default '') returns public.pos_sales language plpgsql security definer set search_path='' as $$ declare v_user uuid:=auth.uid(); v_total numeric; v_sale public.pos_sales%rowtype; begin if v_user is null or not public.has_role('merchant'::public.app_role) then raise exception 'Merchant authorization required'; end if; if not exists(select 1 from public.stores where id=p_store_id and owner_id=v_user) then raise exception 'Store unauthorized'; end if; if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Items required'; end if; if exists(select 1 from jsonb_to_recordset(p_items) x(menu_item_id uuid,quantity integer) where quantity is null or quantity<1 or quantity>100) then raise exception 'Invalid quantity'; end if; select sum(m.price*x.quantity) into v_total from jsonb_to_recordset(p_items) x(menu_item_id uuid,quantity integer) join public.menu_items m on m.id=x.menu_item_id and m.store_id=p_store_id; if v_total is null then raise exception 'Invalid items'; end if; insert into public.pos_sales(store_id,actor_id,total,note) values(p_store_id,v_user,v_total,left(coalesce(trim(p_note),''),500)) returning * into v_sale; insert into public.pos_sale_items(sale_id,menu_item_id,name_snapshot,unit_price,quantity) select v_sale.id,m.id,m.name,m.price,x.quantity from jsonb_to_recordset(p_items) x(menu_item_id uuid,quantity integer) join public.menu_items m on m.id=x.menu_item_id and m.store_id=p_store_id; return v_sale; end $$; revoke all on function public.create_pos_sale(uuid,jsonb,text) from public,anon; grant execute on function public.create_pos_sale(uuid,jsonb,text) to authenticated;
